-- Owner-facing balancing APIs; normal balancing never requires a source edit.
create or replace function public.admin_update_foundation_store(p_breed text,p_active boolean,p_inventory_size integer,p_price integer,p_rotation_minutes integer) returns void language plpgsql security definer set search_path=public as $$begin perform require_super_admin();if p_inventory_size not between 1 and 12 or p_price<0 or p_rotation_minutes not between 15 and 1440 then raise exception 'Store values are outside supported ranges';end if;update foundation_breeds set active=p_active,store_inventory_size=p_inventory_size,store_price=p_price,store_rotation_minutes=p_rotation_minutes where name=p_breed;if not found then raise exception 'Foundation breed not found';end if;end$$;
create or replace function public.admin_update_store_product(p_id text,p_name text,p_description text,p_price integer,p_active boolean,p_probability numeric default null,p_min integer default null,p_max integer default null,p_stats text[] default null,p_slot text default null,p_quality text default null,p_bonuses jsonb default '{}',p_disciplines text[] default '{}') returns void language plpgsql security definer set search_path=public as $$begin perform require_super_admin();if p_price<0 or(p_probability is not null and(p_probability<0 or p_probability>1))or(p_min is not null and p_max<p_min)then raise exception 'Product values are outside supported ranges';end if;update store_products set name=left(trim(p_name),100),description=left(coalesce(p_description,''),500),price=p_price,active=p_active,feed_success_probability=p_probability,development_min=p_min,development_max=p_max,eligible_stats=p_stats,tack_slot=p_slot,quality=p_quality,tack_bonuses=coalesce(p_bonuses,'{}'),discipline_orientation=coalesce(p_disciplines,'{}')where id=p_id;if not found then raise exception 'Store product not found';end if;end$$;
create or replace function public.admin_update_horse_game_config(p_changes jsonb) returns public.horse_game_config language plpgsql security definer set search_path=public as $$declare result horse_game_config;begin perform require_super_admin();update horse_game_config set real_days_per_horse_year=coalesce((p_changes->>'real_days_per_horse_year')::numeric,real_days_per_horse_year),readiness_health_weight=coalesce((p_changes->>'readiness_health_weight')::numeric,readiness_health_weight),readiness_hooves_weight=coalesce((p_changes->>'readiness_hooves_weight')::numeric,readiness_hooves_weight),readiness_recovery_weight=coalesce((p_changes->>'readiness_recovery_weight')::numeric,readiness_recovery_weight),training_recovery_wear=coalesce((p_changes->>'training_recovery_wear')::integer,training_recovery_wear),show_recovery_wear=coalesce((p_changes->>'show_recovery_wear')::integer,show_recovery_wear),show_hoof_wear=coalesce((p_changes->>'show_hoof_wear')::integer,show_hoof_wear),passive_recovery_per_real_day=coalesce((p_changes->>'passive_recovery_per_real_day')::numeric,passive_recovery_per_real_day),very_poor_threshold=coalesce((p_changes->>'very_poor_threshold')::integer,very_poor_threshold),poor_threshold=coalesce((p_changes->>'poor_threshold')::integer,poor_threshold),fair_threshold=coalesce((p_changes->>'fair_threshold')::integer,fair_threshold),good_threshold=coalesce((p_changes->>'good_threshold')::integer,good_threshold)where id=true returning * into result;if abs(result.readiness_health_weight+result.readiness_hooves_weight+result.readiness_recovery_weight-1)>.001 then raise exception 'Readiness weights must total 1';end if;return result;end$$;
revoke all on function admin_update_foundation_store(text,boolean,integer,integer,integer),admin_update_store_product(text,text,text,integer,boolean,numeric,integer,integer,text[],text,text,jsonb,text[]),admin_update_horse_game_config(jsonb) from public;
grant execute on function admin_update_foundation_store(text,boolean,integer,integer,integer),admin_update_store_product(text,text,text,integer,boolean,numeric,integer,integer,text[],text,text,jsonb,text[]),admin_update_horse_game_config(jsonb) to authenticated;
